pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address actor, bytes32 guessHash) public {
        // Restrict to valid Ethereum value (1 ether) for the lock-in requirement
        amount = bound(amount, 1 ether, 1 ether);
        vm.assume(actor != address(0));
        vm.deal(actor, amount);
        vm.prank(actor);
        try c.lockInGuess{value: amount}(guessHash) { } catch { }
        // Retrieve the block stored in the sender's Guess struct via the public getter
        (uint256 storedBlock, ) = c.guesses(actor);
        // If the lockInGuess succeeded (stored guess != 0), the block must be the next block number
        if (storedBlock != 0) {
            assertEq(storedBlock, block.number + 1);
        } else {
            // LockInGuess may have reverted; in the mutant, storedBlock remains 0, violating the property
            assertTrue(storedBlock != 0, "After successful lockInGuess, storedBlock must be non-zero");
        }
    }
}

