pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 guessHash, address actor) public {
        // Restrict to a wide domain: actor must be able to send ETH and not be the zero address
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));

        // Give the actor enough ETH to call lockInGuess
        vm.deal(actor, 2 ether);

        // Record initial contract balance
        uint256 initialBalance = address(c).balance;

        // Actor locks in a guess
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guessHash);

        // For the property to hold, the lockInGuess must have succeeded.
        // In both versions, if the call succeeded, the guess is stored.
        // Now we move past the block in which the guess *would* be locked in the reference version
        // (block.number + 1). Since we don't know the current block exactly in the fuzzer,
        // we simply advance by 2 blocks to be safely past any plausible lock block.
        vm.roll(block.number + 2);

        // Actor settles
        vm.prank(actor);
        c.settle();

        // After settle, the contract balance must be reduced by exactly 2 ether if the guess was correct,
        // or remain the same if not. In both versions, a correct guess should pay out.
        // However, the bug leaves guesses[actor].block = 0, so blockhash(0) is used.
        // blockhash(0) is the zero hash (0x00...00) which is the default unset guess.
        // If the fuzzer sets guessHash to a non-zero value, the guess will never match,
        // and settle will never pay out. But if the fuzzer sets guessHash to keccak256(abi.encodePacked(blockhash(0))),
        // the guess matches, and the mutant pays out incorrectly because it uses blockhash(0) instead of requiring
        // the actual block's hash. The reference would never pay out because it requires block.number > block.number+1
        // which is impossible until the next block, and then uses the correct blockhash.
        // The general rule: settle never pays out until at least 2 blocks after lockInGuess,
        // and always uses the correct blockhash. Since we can't easily check the exact blockhash,
        // we check a simpler invariant: if the guess is non-zero, the balance must never decrease
        // because the reference can never match a non-zero guess on the very next block
        // (it requires block.number > lockBlock). The bug, however, can match immediately
        // on block.number+1 if guessHash matches blockhash(0), but more reliably,
        // the bug can match incorrectly because it uses blockhash(0) for any non-zero guess if the fuzzer
        // hasn't set it to the hash of zero. Wait, the reference sets lockBlock to block.number+1.
        // Then settle requires block.number > lockBlock, so at least block.number+2.
        // At that point, blockhash(lockBlock) is blockhash(block.number+1) from the original transaction,
        // which is not yet available in the EVM? Actually, blockhash is only available for the last 256 blocks
        // EXCEPT the current block. Since settle is called at block.number+2, blockhash(block.number+1) IS available.
        // So reference works correctly. Mutant has lockBlock = 0, so blockhash(0) is always zero.
        // If the actor guesses the hash of zero, both pay out. If the actor guesses any other hash,
        // reference never pays out (because the guess doesn't match the actual blockhash),
        // but mutant might pay out if blockhash(0) happens to equal the guess? blockhash(0) is constant zero.
        // So the mutant pays out if guessHash == keccak256(abi.encodePacked(bytes32(0))).
        // That's a specific value, but we can't control what the fuzzer gives?
        // The fuzzer will eventually try that value.
        // The property: the balance of C must never decrease after settle if the guess is non-zero AND the block
        // in which lockInGuess was called is not the one whose hash is guessed.
        // Simpler: In the reference, after lockInGuess, settle should never succeed (reduce balance)
        // until at least 2 blocks have passed. Since we advance 2 blocks, settle can succeed.
        // But the difference is the block used for hash. The reference uses the block AFTER lockInGuess,
        // the mutant uses block 0. So if the fuzzer provides a guessHash that equals keccak256(abi.encodePacked(bytes32(0))),
        // the mutant pays out, but the reference doesn't (unless the actual blockhash happens to be zero, probability negligible).
        // So the rule: After a successful lockInGuess, if settle is called, the contract's balance can only decrease
        // if the guessHash matches the correct blockhash. Since the correct blockhash is unpredictable by the fuzzer,
        // the reference's balance should almost never decrease. We can assert that the balance remains exactly initialBalance
        // for all inputs where guessHash != keccak256(abi.encodePacked(bytes32(0)))? But that's not a general rule,
        // it's a statistical property. We need a deterministic rule.
        // Better: The reference requires guesses[msg.sender].block != 0 to proceed in settle. The mutant sets it to 0,
        // so settle would always revert? No, the require is block.number > guesses[msg.sender].block.
        // In the mutant, block is 0, so block.number > 0 is always true (except block 0, but we're past that).
        // So settle does NOT revert. The difference is that the reference requires the sender to have locked in a guess,
        // but the mutant allows settle without a proper lock. However, we already called lockInGuess, so the guess struct exists.
        // The bug is that the block number is 0, so settle uses blockhash(0) which is zero.
        // The invariant: After lockInGuess, the value of guesses[msg.sender].block must be non-zero.
        // That was already tried and failed because "guesses" is not public? In the contract, guesses is private.
        // There's no getter. So we cannot read it.
        // We need an observable effect. The observable effect is that the mutant can never correctly settle?
        // No, the mutant can settle and might pay out if guess matches blockhash(0).
        // The reference will also settle and might pay out if guess matches blockhash(block.number+1).
        // Since we advanced 2 blocks, the reference can pay out if the guess is correct, but the fuzzer can't guess it.
        // So the reference will almost never pay out, but the mutant will pay out whenever guessHash == keccak256(abi.encodePacked(bytes32(0))).
        // That is a specific value. We can let the fuzzer try it.
        // The assertion: the contract balance must not decrease unless the guess is correct.
        // But correctness is defined differently. In the reference, correctness depends on block.number+1.
        // In the mutant, it depends on block 0.
        // The general rule: The reference's settle function never pays out based on blockhash(0).
        // The mutant does. So we can assert that after settle, if the balance decreased, the guessHash cannot be
        // the hash of zero? No, because the reference might also pay out for hash of zero if blockhash(block.number+1) is zero?
        // Probability is 1/2^256, negligible. So we can assert: balance never decreases.
        // But that's not strictly true for all inputs in the reference; the fuzzer could by chance guess the correct future blockhash.
        // So that's not a sound deterministic property.
        // We need a property that holds for ALL inputs in the reference. The difference is the block number stored.
        // Since we cannot read the stored block number, we must observe it via revert or another function.
        // What if we call lockInGuess again with the same actor? The require is guesses[msg.sender].block == 0.
        // In the reference, after first lockInGuess, block is set to non-zero, so second lockInGuess reverts.
        // In the mutant, block remains 0, so second lockInGuess succeeds (if actor has another 1 ether).
        // That is a clean observable difference: the mutant allows a second lockInGuess for the same address without settle,
        // while the reference doesn't. And we can observe it by checking the return/revert of lockInGuess.
        // That's a universal property: "No address can call lockInGuess twice successfully without an intervening settle."
        // Let's test: actor calls lockInGuess once, then calls it again. The reference reverts on the second call.
        // The mutant succeeds. This requires no adversarial helper, just two calls.
        // This is a general rule that the reference satisfies for EVERY input, and the bug breaks for at least some input.
        // Indeed, after one lockInGuess, the actor's block is non-zero (reference) or 0 (mutant). So second call reverts or not.
        // We can assert that the second call always fails in the reference.
        // That's perfect.

        // Give the actor enough for two calls (2 ether)
        // Already gave 2 ether. First call used 1 ether, leaving 1 ether.
        // Now second call:
        vm.prank(actor);
        (bool success, ) = address(c).call{value: 1 ether}(abi.encodeWithSignature("lockInGuess(bytes32)", guessHash));
        // In the reference, this call must fail (revert). In the mutant, it succeeds.
        // We assert that the call failed.
        assertTrue(!success);
    }
}

