pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed) public {
        bytes32 hash = bytes32(seed);
        address actor = address(uint160(uint256(keccak256(abi.encode(seed)))));
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        vm.assume(actor != address(c));
        vm.deal(actor, 2 ether);
        vm.deal(address(c), 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(hash);
        uint guessBlock = uint256(keccak256(abi.encode(seed))) % 256 + 1;
        vm.roll(guessBlock + 2);
        vm.prank(actor);
        bool settled = true;
        try c.settle() { settled = true; } catch { settled = false; }
        assertTrue(settled ? address(c).balance == 0 : address(c).balance == 1 ether);
    }
}

