pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 guess) public {
        // The solver calls lockInGuess and settle in the same transaction.
        // In the correct version, block.number < recorded block, so settle
        // cannot succeed. In the buggy version, block.number == recorded block,
        // so settle can succeed because the blockhash is known.
        address solver = address(0x1337);
        vm.deal(solver, 1 ether);
        vm.deal(address(c), 2 ether); // ensure balance for payout

        // Compute the expected blockhash answer for the current block
        bytes32 answer = keccak256(abi.encodePacked(blockhash(block.number)));
        bytes32 hashedGuess = guess; // fuzzer provides a guess that may match answer

        vm.startPrank(solver);
        c.lockInGuess{value: 1 ether}(hashedGuess);
        bool settled;
        try c.settle() {
            settled = true;
        } catch {
            settled = false;
        }
        vm.stopPrank();

        // The reference contract must never settle in the same transaction,
        // regardless of the guess value.
        // The buggy contract can settle if hashedGuess equals the known answer.
        if (hashedGuess == answer) {
            // Buggy contract would allow settlement; correct contract must not.
            assertTrue(!settled, "Reference must not settle in the same block");
        } else {
            // Neither should settle.
            assertTrue(!settled, "Must not settle in the same block");
        }
    }
}

