pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = (new C){value: 1 ether}();
    }
    function testFuzz_property(uint256 fuzzedBlockNumber, bytes32 fuzzedGuessHash) public {
        // Bound block number to be at least 1 to avoid underflow when adding 1
        bound(fuzzedBlockNumber, 1, type(uint64).max);
        // Set the block number to the fuzzed value before the call
        vm.roll(fuzzedBlockNumber);

        // Prepare the caller with sufficient ether
        address caller = address(0x1234);
        vm.deal(caller, 1 ether);
        vm.prank(caller);
        c.lockInGuess{value: 1 ether}(fuzzedGuessHash);

        // Retrieve the stored block number via the auto-generated getter for public mapping.
        // The getter for 'guesses' takes an address and returns (uint,bytes32).
        (uint storedBlock, ) = c.guesses(caller);

        // Assert that the stored block is exactly block.number + 1
        assertTrue(storedBlock == fuzzedBlockNumber + 1);
    }
}

