pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 guess) public {
        // Set up the contract with 2 ether to pay out a correct guess
        vm.deal(address(c), 2 ether);
        // Fuzzed guesser address (EOA) and the guess itself
        address guesser = address(0x1234);
        vm.deal(guesser, 1 ether);

        // lockInGuess with the fuzzed guess
        vm.prank(guesser);
        c.lockInGuess{value: 1 ether}(guess);

        // Move past the recorded block so settle will use blockhash
        // The correct contract records block.number+1, so we advance by 2 blocks
        vm.roll(block.number + 2);

        // Try to settle
        vm.prank(guesser);
        bool ok = false;
        try c.settle() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: settle must succeed (not revert) for any valid lockInGuess
        // when we advance well past the recorded block.
        // The reference C records block.number+1, so after +2 blocks the blockhash is available -> success.
        // The bug records block.number+2, so after +2 blocks the blockhash for that future block
        // is not yet available (blockhash only for < current block) -> settle reverts.
        assertTrue(ok);
    }
}

