pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 guessHash, uint8 futureBlocks) public {
        vm.assume(futureBlocks >= 2 && futureBlocks <= 20);

        address guesser = address(0x1234);
        vm.deal(guesser, 2 ether);

        vm.deal(address(c), 2 ether);

        vm.prank(guesser);
        c.lockInGuess{value: 1 ether}(guessHash);

        vm.roll(block.number + futureBlocks);

        bytes32 answer = keccak256(abi.encodePacked(blockhash(block.number - futureBlocks + 1)));
        if (guessHash == answer) {
            uint256 balanceBefore = address(c).balance;

            vm.prank(guesser);
            bool settled;
            try c.settle() { settled = true; } catch { settled = false; }

            if (settled) {
                assertTrue(address(c).balance == balanceBefore - 2 ether);
            } else {
                assertTrue(address(c).balance == balanceBefore);
            }
        } else {
            // irrelevant case, just skip
        }
    }
}

